"""GET /flights/<flight_id> -> flight-get (blueprint S1).

Port of app.py:51-55 + catalog.get_flight + storage.get_flight:
flight_id is used as the key without format validation; a hit answers the
whole item (no field filtering); a miss -- or a read failure swallowed into
None by the data layer -- answers the same ValueError('Flight with ID <id>
not found') -> 400, so 'missing' and 'read failed' are indistinguishable
(business_rules[2]). The service-layer None->raise hop is collapsed into the
handler (business_rules[3] allows it; status code and text kept identical).
Default boto3 retry settings reproduce flight-get-throttle-once.
"""
import json
import os

import boto3

import storage

# global init: once per cold start; table names come from the environment
# injected by the template (D-11, GAP-22)
dynamodb = boto3.resource('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))


def _cors_headers(event):
    """global_middleware[0] (flask-cors CORS(app), D-4/D-10, GM1): echo the
    request's Origin verbatim (Vary: Origin only then), otherwise '*'.
    Access-Control-Allow-Methods / Access-Control-Allow-Headers belong to the
    preflight (OPTIONS) path only; the gateway's Cors block answers OPTIONS."""
    origin = None
    for name, value in (event.get('headers') or {}).items():
        if isinstance(name, str) and name.lower() == 'origin':
            origin = value
            break
    headers = {'Content-Type': 'application/json'}
    if origin:
        headers['Access-Control-Allow-Origin'] = origin
        headers['Vary'] = 'Origin'
    else:
        headers['Access-Control-Allow-Origin'] = '*'
    if str(event.get('httpMethod') or '').upper() == 'OPTIONS':
        headers['Access-Control-Allow-Methods'] = 'DELETE, GET, HEAD, OPTIONS, PATCH, POST, PUT'
        headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
    return headers


def _json(status_code, payload, event):
    return {
        'statusCode': status_code,
        'headers': _cors_headers(event),
        'body': json.dumps(payload),
    }




def _path_params(event):
    """Path parameters as API Gateway hands them (payload 1.0). The fallback
    derives the identical values from event.resource + event.path for
    harnesses that omit pathParameters; a real gateway always provides them,
    so the branch never fires in production."""
    params = event.get('pathParameters')
    if params:
        return params
    resource = str(event.get('resource') or '')
    path = str(event.get('path') or '')
    out = {}
    rsegs, psegs = resource.split('/'), path.split('/')
    for i, seg in enumerate(rsegs):
        if (seg.startswith('<') and seg.endswith('>')) or (seg.startswith('{') and seg.endswith('}')):
            key = seg.strip('<>{}+').split(':')[-1]
            if i < len(psegs):
                out[key] = psegs[i]
    return out

def _handle(event):
    flight_id = _path_params(event).get('flight_id')
    flight = storage.get_flight(dynamodb, os.environ['FLIGHT_TABLE'], flight_id)
    if not flight:
        raise ValueError(f"Flight with ID {flight_id} not found")
    return _json(200, flight, event)


def lambda_handler(event, context):
