        body = {"Successful": [{"Id": e["Id"], "MessageId": str(uuid.uuid4()), "MD5OfMessageBody": _md5(e["MessageBody"])} for e in req["Entries"]],
                "Failed": []}
    else:
        raise RuntimeError(f"perf-shim: no stub for {op}")
    return body, cu


