def record_item_keys(record):
    """[R4] Items ("table|key") one message will read or write, from the same
    parse the handler uses; [] when the message is skipped before any call.
    The consumer writes exactly one item, with the deterministic key
    id=bookingId (SI-9/D-5), so that key is also the idempotency marker: two
    messages of the same booking land in different waves."""
    try:
        body = json.loads(record.get('body') or '')
    except Exception:
        return []          # undecodable payload: dropped before any call
    if not isinstance(body, dict):
        return []          # non-object body: dropped before any call
    booking_id = body.get('bookingId')
    customer_id = body.get('customerId')
    points = body.get('points')
    if not booking_id or not customer_id:
        return []          # missing identity: dropped before any call
    if not isinstance(points, (int, float)) or points <= 0:
        return []          # invalid points: dropped before any call
    key = json.dumps({'id': booking_id}, sort_keys=True)
    return [os.environ['LOYALTY_TABLE'] + '|' + key]


def schedule_waves(records, keys_of):
    """[R4] A message goes one wave after the latest earlier message it shares
    an item with: messages of one wave touch disjoint items, and every item
    still sees the messages in batch order."""
    last_wave, waves = {}, []
    for record in records:
        keys = keys_of(record)
        wave = max((last_wave[k] + 1 for k in keys if k in last_wave), default=0)
        for k in keys:
            last_wave[k] = wave
        if wave == len(waves):
            waves.append([])
        waves[wave].append(record)
    return waves


def run_in_waves(records, keys_of, handle):
    """[R4] Waves one after another, the messages of a wave on the thread pool;
    a wave of one message runs in this thread (no pool overhead). An exception
    a message did not handle is re-raised after its wave."""
    for wave in schedule_waves(records, keys_of):
        if len(wave) == 1:
            handle(wave[0])
            continue
        futures = [_POOL.submit(handle, record) for record in wave]
        wait(futures)
        for future in futures:
            future.result()


def lambda_handler(event, context):
    """SQS batch entry point; failures are reported per record, never raised."""
    records = (event or {}).get('Records', [])
    failures = []

    def handle_record(record):  # [R4] was: for record in records:
        try:
            redeliver = _process_record(record)
        except Exception as e:
            # An unexpected classification bug must not stall the batch:
            # report the record so the event source mapping can retry it.
            print(f"Warning: unexpected consumer error, requesting redelivery: {str(e)}")
            redeliver = True
        if redeliver and record.get('messageId'):
            failures.append({'itemIdentifier': record['messageId']})

    run_in_waves(records, record_item_keys, handle_record)
    # [R4] Batch order, as the sequential loop reported them.
    order = {record.get('messageId'): index for index, record in enumerate(records)}
    failures.sort(key=lambda failure: order[failure['itemIdentifier']])
    return {'batchItemFailures': failures}

