Port of app.py:269-296 + the decorator. All four steps stay inline in the
monolith's order (SI-3/D-6): ownership read #1 (404/403) -> route's
BookingService.get_booking read #2 (missing -> 400 'Booking <id> not found',
fault booking-cancel-second-read-fails) -> cancel_booking's internal read #3
(missing -> 400 'Invalid booking ID: <id>', fault third-read-fails) + status
update (row kept, bookingReference NOT cleared) -> seat release (failure only
logged, response still 200, seat stuck) -> refund via paymentToken (the try
swallows both a raising refund and the KeyError of a row without paymentToken
into refund {refundId: 'N/A', status: 'failed'}) -> notify_booking(customer, 0,
None) NOT wrapped: a row missing 'customer' answers 500 {error, type: 'KeyError'}
with the status already CANCELLED (business_rules[7] asymmetry kept). Reads #1-3
are kept deliberately (SI-2).
"""

import json
import os

import boto3

import storage
import payments
import services

# global init: once per cold start; table names come from the environment
# injected by the template (D-11, GAP-22); no config.py / .env / STAGE suffixes
dynamodb = boto3.resource('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))


def _claims(event):
    """Identity handed over by the gateway authorizer (SI-6/SI-7): the business
    user id is claims.sub; nothing else is read from the token, no token code
    lives in the function (D-1: auth is infrastructure)."""
    authorizer = (event.get('requestContext') or {}).get('authorizer') or {}
    return authorizer.get('claims') or {}


def _cors_headers(event):
    """global_middleware[0] (flask-cors CORS(app), D-4/D-10, GM1): echo the
----- 100-155
def _handle(event):
    booking_id = _path_params(event).get('booking_id')
    # booking_owner_or_admin_required (auth.py:220-237) as route-internal
    # logic: read #1 -- missing row answers 404 before any ownership talk.
    booking = storage.get_booking(dynamodb, os.environ['BOOKING_TABLE'], booking_id)
    if not booking:
        return _json(404, {'error': 'Booking not found'}, event)
    sub = _claims(event).get('sub')
    if sub != booking['customer'] and not storage.is_admin(dynamodb, os.environ['USER_GROUPS_TABLE'], sub):
        # Admin check reads UserGroupsTable (D-3); a missing row or a failed
        # read is groups=[] -- it never turns into a 401 (D-13/SI-13).
        return _json(403, {'error': 'Access denied. You can only access your own bookings.'}, event)

    # BookingService.get_booking -- read #2, kept per SI-2
    booking = services.get_booking(booking_id, dynamodb, os.environ['BOOKING_TABLE'])

    # BookingService.cancel_booking -- read #3 + the conditional update
    services.cancel_booking(booking_id, dynamodb, os.environ['BOOKING_TABLE'])

    # release the flight seat; failure only logs (booking stays CANCELLED)
    try:
        storage.release_flight_seat(dynamodb, os.environ['FLIGHT_TABLE'], booking['bookingOutboundFlightId'])
    except Exception as e:
        print(f"Warning: Failed to release flight seat: {str(e)}")

    # refund the payment; this try also swallows the KeyError of a stored row
    # without paymentToken (wb-cancel-row-without-paymenttoken, J4-2)
    try:
        refund_result = payments.refund_payment(dynamodb, os.environ['PAYMENTS_TABLE'], booking['paymentToken'])
    except Exception as e:
        print(f"Warning: Failed to refund payment: {str(e)}")
        refund_result = {'refundId': 'N/A', 'status': 'failed'}

    # notification is NOT wrapped: a row missing 'customer' answers 500
    # {error, type: 'KeyError'} after the status was already flipped
    notification = services.notify_booking(booking['customer'], 0, None)

    return _json(200, {
        'bookingId': booking_id,
        'status': 'CANCELLED',
        'refund': refund_result,
        'notification': notification,
    }, event)


def lambda_handler(event, context):
    """Uniform exception exit replicated from app.py:28-36 (D-10/GAP-11):
    ValueError -> 400 {error, type}, anything else -> 500 {error, type};
    the CORS headers ride on the error responses too."""
    try:
        return _handle(event)
    except ValueError as e:
        return _json(400, {'error': str(e), 'type': 'ValueError'}, event)
    except Exception as e:
        return _json(500, {'error': str(e), 'type': type(e).__name__}, event)

